local config = {
  str_homestory_N21yongchi_90020101_1_dialog_content = "Wah, panas sekali...",
  str_homestory_N21yongchi_90020101_2_dialog_content = "Ya, aku merasa cuaca belakangan ini jauh lebih hangat.",
  str_homestory_N21yongchi_90020101_3_dialog_content = "Bahkan tanaman di Cloud Gardens tampaknya sudah cukup mendapat sinar matahari.",
  str_homestory_N21yongchi_90020101_4_dialog_content = "Aku mulai merindukan Harbour City.",
  str_homestory_N21yongchi_90020101_5_dialog_content = "Angin sepoi-sepoi, lautan di musim panas...",
  str_homestory_N21yongchi_90020101_6_dialog_content = "Oh, dan bisa pergi berenang bersama...",
  str_homestory_N21yongchi_90020101_7_dialog_content = "Ya, tidak ada tempat untuk berenang di Cloud Gardens.",
  str_homestory_N21yongchi_90020101_8_dialog_content = "Jadi, mungkin kita harus membuatnya di suatu tempat?",
  str_homestory_N21yongchi_90020101_9_dialog_content = "Saya pikir orang mungkin seperti itu.",
  str_homestory_N21yongchi_90020101_10_dialog_content = "Ide yang bagus!",
  str_homestory_N21yongchi_90020101_11_dialog_content = "Kami sudah membangun banyak bangunan. Mengapa tidak memiliki Taman Air Cloud Gardens?",
  str_homestory_N21yongchi_90020101_12_dialog_content = "Kedengarannya seperti Anda punya rencana.",
  str_homestory_N21yongchi_90020101_13_dialog_content = "Belum. Tapi saya pasti ingin taman air.",
  str_homestory_N21yongchi_90020101_14_dialog_content = "Kita akan membutuhkan banyak air. Dan di suatu tempat untuk menaruh air.",
  str_homestory_N21yongchi_90020101_15_dialog_content = "Mari kita mulai dengan menggali kolam renang.",
  str_homestory_N21yongchi_90020101_16_dialog_content = "Sebuah kolam yang cukup besar untuk menampung banyak Aurorian akan berarti banyak spadework.",
  str_homestory_N21yongchi_90020101_17_dialog_content = "Pasti ada seorang Aurorian yang pandai dalam penggalian dan konstruksi. Biarkan aku berpikir...",
  str_homestory_N21yongchi_90020101_18_dialog_content = "Itu mengingatkanku, Ciel adalah orang yang kau butuhkan. Dia punya banyak pengalaman dengan pekerjaan semacam ini.",
  str_homestory_N21yongchi_90020101_19_dialog_content = "Ciel? Mengerti!",
  str_homestory_N21yongchi_90020101_20_dialog_content = "Aku akan pergi dan berbicara dengannya.",
  str_homestory_N21yongchi_90020102_1_dialog_content = "Ciel!",
  str_homestory_N21yongchi_90020102_2_dialog_content = "Ah! Oh itu kamu, PlayerName.",
  str_homestory_N21yongchi_90020102_3_dialog_content = "Maaf, apakah saya membuat Anda takut?",
  str_homestory_N21yongchi_90020102_4_dialog_content = "Tidak. Saya hanya berkonsentrasi untuk membuat beberapa penyesuaian pada Styx.",
  str_homestory_N21yongchi_90020102_5_dialog_content = "Apakah ada yang salah dengan itu?",
  str_homestory_N21yongchi_90020102_6_dialog_content = "Saya harap itu tidak berfungsi.",
  str_homestory_N21yongchi_90020102_7_dialog_content = "Tidak, tidak ada yang seperti itu...",
  str_homestory_N21yongchi_90020102_8_dialog_content = "Saya punya ide untuk beberapa penyesuaian yang sangat radikal.",
  str_homestory_N21yongchi_90020102_9_dialog_content = "PlayerName, Anda tahu saya sering membantu Petugas Charon menggali terowongan, bukan?",
  str_homestory_N21yongchi_90020102_10_dialog_content = "Jika perubahan ini berhasil, saya dapat menggandakan kecepatan penggalian Styx.",
  str_homestory_N21yongchi_90020102_11_dialog_content = "Wow, itu luar biasa!",
  str_homestory_N21yongchi_90020102_12_dialog_content = "Masalahnya, performa durasinya turun 90%...",
  str_homestory_N21yongchi_90020102_13_dialog_content = "Itu... kurang mengagumkan.",
  str_homestory_N21yongchi_90020102_14_dialog_content = "Ya, jadi saya harus terus mengerjakannya dan melihat apakah saya bisa menemukan perbaikan.",
  str_homestory_N21yongchi_90020102_15_dialog_content = "Aku tahu.",
  str_homestory_N21yongchi_90020102_16_dialog_content = "Nah, jika ada yang bisa saya bantu, beri tahu saya.",
  str_homestory_N21yongchi_90020102_17_dialog_content = "Ah, masa?",
  str_homestory_N21yongchi_90020102_18_dialog_content = "Sebenarnya... ada sesuatu yang bisa kau lakukan untukku, PlayerName.",
  str_homestory_N21yongchi_90020102_19_dialog_content = "Tentu. Sebut saja!",
  str_homestory_N21yongchi_90020102_20_dialog_content = "Bisakah Anda mendapatkan saya beberapa bijih?",
  str_homestory_N21yongchi_90020102_21_dialog_content = "Saya membutuhkannya untuk menguji Styx.",
  str_homestory_N21yongchi_90020102_22_dialog_content = "Bukan masalah. Tinggalkan dengan saya.",
  str_homestory_N21yongchi_90020103_1_dialog_content = "Apakah Anda mendapatkan bijih yang saya butuhkan?",
  str_homestory_N21yongchi_90020103_2_dialog_content = "Tentu saja! ({1}/{2})",
  str_homestory_N21yongchi_90020103_3_dialog_content = "Terima kasih! Aku tahu aku bisa mengandalkanmu, PlayerName.",
  str_homestory_N21yongchi_90020103_4_dialog_content = "Dan kamu juga sangat cepat.",
  str_homestory_N21yongchi_90020103_5_dialog_content = "Hehe. Saya pikir semua pekerjaan yang saya lakukan di sini di Cloud Gardens membuat saya lebih kuat.",
  str_homestory_N21yongchi_90020103_6_dialog_content = "Pekerjaan seperti ini tampaknya sangat mudah sekarang.",
  str_homestory_N21yongchi_90020103_7_dialog_content = "Dan ketika itu terjadi, saya juga ingin meminta Anda.",
  str_homestory_N21yongchi_90020103_8_dialog_content = "Ya aku tahu. Kolam renang, kan?",
  str_homestory_N21yongchi_90020103_9_dialog_content = "Hah? Bagaimana kau tahu itu, Ciel?",
  str_homestory_N21yongchi_90020103_10_dialog_content = "Nona Carleen datang menemui saya saat Anda sedang mengumpulkan bijih.",
  str_homestory_N21yongchi_90020103_11_dialog_content = "Serahkan padaku. Yang perlu Anda lakukan adalah menandai area di mana Anda ingin membangun kolam renang.",
  str_homestory_N21yongchi_90020103_12_dialog_content = "Saya akan datang dan membantu setelah saya selesai dengan Styx.",
  str_homestory_N21yongchi_90020103_13_dialog_content = "Oke. Terima kasih banyak.",
  str_homestory_N21yongchi_90020103_14_dialog_content = "Tidak cukup.",
  str_homestory_N21yongchi_90020103_15_dialog_content = "Yah, aku mengandalkanmu.",
  str_homestory_N21yongchi_90020104_1_dialog_content = "Huff, puff... Ini akan memberitahu Ciel di mana aku ingin kolam renang.",
  str_homestory_N21yongchi_90020104_2_dialog_content = "Saya tidak terbiasa menggali seperti itu. Ini pekerjaan yang sulit.",
  str_homestory_N21yongchi_90020104_3_dialog_content = "Saya bahkan tidak bisa membayangkan harus menggali seluruh kolam renang sendirian.",
  str_homestory_N21yongchi_90020104_4_dialog_content = "Tapi ini harus cukup. Sekarang yang harus saya lakukan adalah menunggu Ciel.",
  str_homestory_N21yongchi_90020104_5_dialog_content = "Dan... selesai!",
  str_homestory_N21yongchi_90020104_6_dialog_content = "Wow! Itu tidak bisa dipercaya.",
  str_homestory_N21yongchi_90020104_7_dialog_content = "Ciel, kamu hebat!",
  str_homestory_N21yongchi_90020104_8_dialog_content = "Yah, itu bukan hanya aku. Saya tidak bisa melakukannya tanpa Styx.",
  str_homestory_N21yongchi_90020104_9_dialog_content = "Dan Miss Carleen memberi saya banyak nasihat.",
  str_homestory_N21yongchi_90020104_10_dialog_content = "Tapi masih belum terlihat sempurna.",
  str_homestory_N21yongchi_90020104_11_dialog_content = "Anda mungkin perlu melakukan pemolesan, PlayerName.",
  str_homestory_N21yongchi_90020104_12_dialog_content = "Saya pikir itu sudah luar biasa. Dan jauh lebih baik daripada yang bisa saya dan sekop saya lakukan.",
  str_homestory_N21yongchi_90020104_13_dialog_content = "Serahkan pembersihannya padaku, Ciel.",
  str_homestory_N21yongchi_90020105_1_dialog_content = "Ya! Saya sudah membersihkan kolam renang, dan sekarang orang bisa menggunakannya.",
  str_homestory_N21yongchi_90020105_2_dialog_content = "Aku akan pergi dan memberitahu Carleen.",
  str_homestory_N21yongchi_90020106_1_dialog_content = "Carleen!",
  str_homestory_N21yongchi_90020106_2_dialog_content = "PlayerName, kamu kembali.",
  str_homestory_N21yongchi_90020106_3_dialog_content = "Apakah Anda mendapatkan bijih untuk Ciel?",
  str_homestory_N21yongchi_90020106_4_dialog_content = "Ya saya telah melakukannya. Dan kolam renang telah dibangun!",
  str_homestory_N21yongchi_90020106_5_dialog_content = "Saya tidak tahu Anda akan berbicara dengan Ciel juga.",
  str_homestory_N21yongchi_90020106_6_dialog_content = "Ya, saya tiba-tiba memikirkan beberapa ide yang mungkin bisa membantu.",
  str_homestory_N21yongchi_90020106_7_dialog_content = "Jadi saya pergi menemuinya dan meneruskannya.",
  str_homestory_N21yongchi_90020106_8_dialog_content = "Saya tidak berpikir kolam renang akan begitu cepat dibangun.",
  str_homestory_N21yongchi_90020106_9_dialog_content = "Yah, itu masih agak dasar. Ini hanya kolam renang dan tidak ada yang lain.",
  str_homestory_N21yongchi_90020106_10_dialog_content = "Saya dapat membantu dengan itu.",
  str_homestory_N21yongchi_90020106_11_dialog_content = "Bagaimanapun, Anda telah bekerja sangat keras untuk menyambut kami semua.",
  str_homestory_N21yongchi_90020106_12_dialog_content = "Kami tidak dapat mengandalkan Anda untuk melakukan semuanya.",
  str_homestory_N21yongchi_90020106_13_dialog_content = "Itu hanya sopan bahwa kami tamu membantu Anda juga.",
  str_homestory_N21yongchi_90020106_14_dialog_content = "Terima kasih, Carleen.",
  str_homestory_N21yongchi_90020106_15_dialog_content = "Meskipun aku tidak pernah menganggapmu sebagai tamu.",
  str_homestory_N21yongchi_90020106_16_dialog_content = "Anda di sini di Cloud Gardens, dan itu membuat Anda menjadi keluarga.",
  str_homestory_N21yongchi_90020106_17_dialog_content = "Dan Taman Air Cloud Gardens akan terbuka untuk setiap Aurorian yang ingin berkunjung.",
  str_homestory_N21yongchi_90020106_18_dialog_content = "Ide yang menarik!",
  str_homestory_N21yongchi_90020201_1_dialog_content = "PlayerName!",
  str_homestory_N21yongchi_90020201_2_dialog_content = "Hai, Vice.",
  str_homestory_N21yongchi_90020201_3_dialog_content = "Saya melewati kolam renang yang indah dalam perjalanan ke sini. Apakah Anda membangunnya?",
  str_homestory_N21yongchi_90020201_4_dialog_content = "Itu tidak ada di sini beberapa hari yang lalu, bukan?",
  str_homestory_N21yongchi_90020201_5_dialog_content = "Tidak. Carleen yang membuat desainnya, lalu Ciel yang mengerjakan konstruksinya.",
  str_homestory_N21yongchi_90020201_6_dialog_content = "Saya pikir itu keren juga!",
  str_homestory_N21yongchi_90020201_7_dialog_content = "Ah, seharusnya aku menduga Carleen berkontribusi. Ada rasa yang pasti dari Lumopolis di sini.",
  str_homestory_N21yongchi_90020201_8_dialog_content = "Dan senang mendengar bahwa Ciel menemukan kegunaan untuk semua keterampilan membangun terowongan yang dia kumpulkan.",
  str_homestory_N21yongchi_90020201_9_dialog_content = "Tepat! Kolam itu tidak akan sebesar itu jika bukan karena bantuannya.",
  str_homestory_N21yongchi_90020201_10_dialog_content = "Tapi itu tidak akan hanya kolam renang. Saya merencanakan taman air untuk semua orang berenang dan bersenang-senang!",
  str_homestory_N21yongchi_90020201_11_dialog_content = "Itu terdengar seperti Anda, PlayerName.",
  str_homestory_N21yongchi_90020201_12_dialog_content = "Dan Anda membuat saya bersemangat sekarang. Bagaimana saya bisa membantu?",
  str_homestory_N21yongchi_90020201_13_dialog_content = "(Saya punya firasat buruk tentang ini.)",
  str_homestory_N21yongchi_90020201_14_dialog_content = "(Ketika Vice mengatakan tolong, apakah yang dia maksud dengan... masakannya?)",
  str_homestory_N21yongchi_90020201_15_dialog_content = "Aku tahu!",
  str_homestory_N21yongchi_90020201_16_dialog_content = "Oh? A-Apa?",
  str_homestory_N21yongchi_90020201_17_dialog_content = "Saya ingat belajar berenang di Illumina.",
  str_homestory_N21yongchi_90020201_18_dialog_content = "Pelatih memberi kami beberapa peralatan keselamatan untuk membantu.",
  str_homestory_N21yongchi_90020201_19_dialog_content = "Seperti bola tiup dan pelampung.",
  str_homestory_N21yongchi_90020201_20_dialog_content = "Dengan begitu kita bisa berlatih berenang dengan lebih aman.",
  str_homestory_N21yongchi_90020201_21_dialog_content = "Dan Aurorian yang belum pernah berenang sebelumnya bisa terbiasa berada di air.",
  str_homestory_N21yongchi_90020201_22_dialog_content = "Aku tahu.",
  str_homestory_N21yongchi_90020201_23_dialog_content = "Saya kira itu agak berbahaya untuk hanya mengisi kolam dengan air ...",
  str_homestory_N21yongchi_90020201_24_dialog_content = "Pemikiran yang bagus, Vice!",
  str_homestory_N21yongchi_90020201_25_dialog_content = "Hehe. Keselamatan harus selalu didahulukan.",
  str_homestory_N21yongchi_90020201_26_dialog_content = "Coba saya pikir, dari mana kita bisa mendapatkan perlengkapan seperti itu...",
  str_homestory_N21yongchi_90020201_27_dialog_content = "Sepertinya aku ingat kapan terakhir kali aku berselancar...",
  str_homestory_N21yongchi_90020201_28_dialog_content = "Saya tahu! Sirkus akan memiliki beberapa.",
  str_homestory_N21yongchi_90020201_29_dialog_content = "Aku harus pergi dan bertanya pada Rainbow.",
  str_homestory_N21yongchi_90020201_30_dialog_content = "Pertahankan kerja bagus! Aku akan menunggumu disini.",
  str_homestory_N21yongchi_90020202_1_dialog_content = "Dia PlayerName! Halo.",
  str_homestory_N21yongchi_90020202_2_dialog_content = "Anda tampaknya dalam suasana hati yang baik. Apa yang terjadi?",
  str_homestory_N21yongchi_90020202_3_dialog_content = "Nah, Cloud Gardens adalah rumah saya. Saya hanya senang bisa kembali ke sini.",
  str_homestory_N21yongchi_90020202_4_dialog_content = "Bagaimana denganmu, Rainbow? Apakah Anda menetap?",
  str_homestory_N21yongchi_90020202_5_dialog_content = "Saya pikir begitu, ya. Lagi pula, saya memiliki banyak petualangan di atas Emerald.",
  str_homestory_N21yongchi_90020202_6_dialog_content = "Jika ada, saya menduga kehidupan di tanah padat sedikit... terlalu stabil.",
  str_homestory_N21yongchi_90020202_7_dialog_content = "Jadi, PlayerName, kenapa tiba-tiba tertarik padaku?",
  str_homestory_N21yongchi_90020202_8_dialog_content = "Aku melihatmu menuju ke arahku dari MILES jauhnya. Apakah Anda membutuhkan sesuatu?",
  str_homestory_N21yongchi_90020202_9_dialog_content = "Haha, Anda telah melihat melalui saya.",
  str_homestory_N21yongchi_90020202_10_dialog_content = "Ini seperti ini: Saya telah membangun kolam renang di Cloud Gardens dan saya ingin membuatnya menjadi taman air.",
  str_homestory_N21yongchi_90020202_11_dialog_content = "Tapi ada banyak Aurorian di sini yang tidak bisa berenang.",
  str_homestory_N21yongchi_90020202_12_dialog_content = "Jadi saya ingin bertanya apakah ada cincin renang cadangan di atas Emerald.",
  str_homestory_N21yongchi_90020202_13_dialog_content = "Ah. Nah, Anda telah datang ke orang yang tepat. Saya bertanggung jawab atas toko peralatan keselamatan.",
  str_homestory_N21yongchi_90020202_14_dialog_content = "Taruhan Anda tidak mengharapkan itu.",
  str_homestory_N21yongchi_90020202_15_dialog_content = "Ha ha! Nah, mengingat berapa banyak pekerjaan yang sudah Anda miliki, Rainbow, saya kira saya tidak akan terkejut menemukan Anda punya satu lagi.",
  str_homestory_N21yongchi_90020202_16_dialog_content = "Jadi, bisakah Anda meminjamkan saya beberapa? Atau saya bisa membelinya dari Anda?",
  str_homestory_N21yongchi_90020202_17_dialog_content = "Yah... kurasa aku tidak bisa. Mereka bukan milikku, mereka milik Emerald. Saya hanya menjaga mereka.",
  str_homestory_N21yongchi_90020202_18_dialog_content = "Meskipun jika Anda bisa membantu saya sedikit, PlayerName...",
  str_homestory_N21yongchi_90020202_19_dialog_content = "Apa pun. Sebut saja.",
  str_homestory_N21yongchi_90020202_20_dialog_content = "Heheh, Anda yakin mudah untuk menangani, PlayerName.",
  str_homestory_N21yongchi_90020202_21_dialog_content = "Pemimpin sirkus kami, Jeno, suka memelihara ikan. Dia terpesona oleh semua spesies yang berbeda di sini di Cloud Gardens.",
  str_homestory_N21yongchi_90020202_22_dialog_content = "Mungkin Anda bisa menangkap beberapa untuknya? Jika Anda melakukannya, saya yakin saya bisa membujuknya untuk memberi Anda beberapa cincin renang.",
  str_homestory_N21yongchi_90020202_23_dialog_content = "Mengerti. Dan saya seorang nelayan juara.",
  str_homestory_N21yongchi_90020202_24_dialog_content = "Tunggu di sana. Aku akan kembali dalam dua kibasan ekor ikan.",
  str_homestory_N21yongchi_90020203_1_dialog_content = "Apakah Anda mendapatkan ikan?",
  str_homestory_N21yongchi_90020203_2_dialog_content = "Tentu saja!({1}/{2})",
  str_homestory_N21yongchi_90020203_3_dialog_content = "Wow, Anda menangkap begitu banyak. Biarkan saya melihat-lihat.",
  str_homestory_N21yongchi_90020203_4_dialog_content = "Hmm, yang ini paling lucu. Sepertinya tipe yang Jeno inginkan.",
  str_homestory_N21yongchi_90020203_5_dialog_content = "Saya telah meninggalkan cincin renang yang Anda inginkan di tepi kolam renang Anda.",
  str_homestory_N21yongchi_90020203_6_dialog_content = "Dan dia juga memberimu ruang ganti yang biasa kami gunakan selama kompetisi. Ini semacam dasar.",
  str_homestory_N21yongchi_90020203_7_dialog_content = "Tapi itu akan memberi pengunjung tempat untuk berganti pakaian dan mandi.",
  str_homestory_N21yongchi_90020203_8_dialog_content = "Terima kasih banyak, Rainbow!",
  str_homestory_N21yongchi_90020203_9_dialog_content = "Jangan menyebutkannya, PlayerName. Meskipun jika Anda tidak sibuk, mungkin Anda bisa mengambil air untuk memelihara ikan ini?",
  str_homestory_N21yongchi_90020203_10_dialog_content = "Saya tidak berpikir mereka punya cukup ruang sekarang. Saya ingin memasukkannya ke dalam wadah yang lebih besar sebelum saya membawanya ke Jeno.",
  str_homestory_N21yongchi_90020203_11_dialog_content = "Tidak masalah. Aku akan segera kembali!",
  str_homestory_N21yongchi_90020203_12_dialog_content = "Aku sedang memikirkannya!",
  str_homestory_N21yongchi_90020203_13_dialog_content = "Lakukan yang terbaik!",
  str_homestory_N21yongchi_90020204_1_dialog_content = "Kamu mengerti?",
  str_homestory_N21yongchi_90020204_2_dialog_content = "Ya!",
  str_homestory_N21yongchi_90020204_3_dialog_content = "Itu cepat. Oke terima kasih.",
  str_homestory_N21yongchi_90020204_4_dialog_content = "Dan saya akan mengambil ikan ini juga.",
  str_homestory_N21yongchi_90020204_5_dialog_content = "Tentu!",
  str_homestory_N21yongchi_90020204_6_dialog_content = "Aku akan pergi ke sana.",
  str_homestory_N21yongchi_90020204_7_dialog_content = "Sedikit air akan melakukannya, terima kasih.",
  str_homestory_N21yongchi_90020205_1_dialog_content = "Oke, itu harus berhasil.",
  str_homestory_N21yongchi_90020205_2_dialog_content = "Dan saya akan meletakkan bola tiup di dekatnya.",
  str_homestory_N21yongchi_90020301_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020301_2_dialog_content = "Hei, Pemimpin Cincin Jeno!",
  str_homestory_N21yongchi_90020301_3_dialog_content = "Aku hanya memikirkanmu! Saya ingin bertanya tentang taman air baru: bagaimana menurut Anda kami dapat memastikan itu sukses?",
  str_homestory_N21yongchi_90020301_4_dialog_content = "Taman air?",
  str_homestory_N21yongchi_90020301_5_dialog_content = "Oh ya, Ciel menyebutkannya.",
  str_homestory_N21yongchi_90020301_6_dialog_content = "Sejujurnya, saya pikir itu sudah terlihat bagus.",
  str_homestory_N21yongchi_90020301_7_dialog_content = "Namun…",
  str_homestory_N21yongchi_90020301_8_dialog_content = "Namun?",
  str_homestory_N21yongchi_90020301_9_dialog_content = "Ia kekurangan sesuatu. Sesuatu yang sangat penting.",
  str_homestory_N21yongchi_90020301_10_dialog_content = "Pikir kembali. Apa memori musim panas Anda yang paling jelas?",
  str_homestory_N21yongchi_90020301_11_option_content = "Gigitan nyamuk.",
  str_homestory_N21yongchi_90020301_12_dialog_content = "Tidak. Maksudku ingatan yang bagus.",
  str_homestory_N21yongchi_90020301_13_option_content = "Ah. Minuman dingin?",
  str_homestory_N21yongchi_90020301_14_dialog_content = "Dekat, tapi tidak.",
  str_homestory_N21yongchi_90020301_15_dialog_content = "Oke, saya hanya akan memberitahu Anda.",
  str_homestory_N21yongchi_90020301_16_dialog_content = "Yang dibutuhkan taman air Anda adalah... es krim.",
  str_homestory_N21yongchi_90020301_17_dialog_content = "Susu dan gula berpadu sempurna pada suhu di bawah nol.",
  str_homestory_N21yongchi_90020301_18_dialog_content = "Memukul lidah Anda seperti kembang api beku di musim panas yang terik.",
  str_homestory_N21yongchi_90020301_19_dialog_content = "Saya tidak tertarik pada makanan manis. Mereka membuat orang bertambah berat badan. Tapi saya tidak bisa memungkiri bahwa es krim juga membuat orang senang.",
  str_homestory_N21yongchi_90020301_20_dialog_content = "Siap!",
  str_homestory_N21yongchi_90020301_21_dialog_content = "Es krim, hmm... Aku akan bicara dengan Vice, dia membuat es serut tahun lalu!",
  str_homestory_N21yongchi_90020301_22_dialog_content = "Terima kasih, Jeno!",
  str_homestory_N21yongchi_90020301_23_dialog_content = "Meninggalkan begitu cepat?",
  str_homestory_N21yongchi_90020301_24_dialog_content = "Apa terburu-buru.",
  str_homestory_N21yongchi_90020302_1_dialog_content = "Vice!",
  str_homestory_N21yongchi_90020302_2_dialog_content = "Hah? Ada apa, PlayerName? Anda kehabisan napas.",
  str_homestory_N21yongchi_90020302_3_dialog_content = "Saya tahu bagaimana kami dapat menarik lebih banyak orang ke Taman Air Cloud Gardens!",
  str_homestory_N21yongchi_90020302_4_dialog_content = "Oh? Yah, jangan membuatku tegang.",
  str_homestory_N21yongchi_90020302_5_dialog_content = "Ingat tahun lalu saat kita membuat es serut?",
  str_homestory_N21yongchi_90020302_6_dialog_content = "Apa, es serut lagi?",
  str_homestory_N21yongchi_90020302_7_dialog_content = "Sejujurnya, saya agak kehilangan minat pada es serut.",
  str_homestory_N21yongchi_90020302_8_dialog_content = "Karena pembicaraan saya dengan Kleken tentang waralaba es serut gagal, ingat?",
  str_homestory_N21yongchi_90020302_9_dialog_content = "Ini bukan es serut!",
  str_homestory_N21yongchi_90020302_10_dialog_content = "Kali ini kita akan membuat es krim!",
  str_homestory_N21yongchi_90020302_11_dialog_content = "Oh, begitu…",
  str_homestory_N21yongchi_90020302_12_dialog_content = "Es serut sebagian besar adalah air, sehingga rasanya selalu sedikit hambar.",
  str_homestory_N21yongchi_90020302_13_dialog_content = "Tapi jika kita menambahkan susu dan buah, atau bahkan daging... Kita bisa menghasilkan jutaan jenis yang berbeda!",
  str_homestory_N21yongchi_90020302_14_dialog_content = "Eh... daging?",
  str_homestory_N21yongchi_90020302_15_dialog_content = "Anda benar, saya seharusnya tidak pernah membatasi diri pada es serut. Dan saya dapat menambahkan dimensi baru pada begitu banyak makanan yang berbeda dengan membekukannya!",
  str_homestory_N21yongchi_90020302_16_dialog_content = "Hah?",
  str_homestory_N21yongchi_90020302_17_dialog_content = "Terima kasih! Anda adalah inspirasi sejati.",
  str_homestory_N21yongchi_90020302_18_dialog_content = "Aku akan datang dengan beberapa sampel. PlayerName, temukan beberapa orang untuk mencicipinya.",
  str_homestory_N21yongchi_90020302_19_dialog_content = "Atau mungkin Anda lebih suka mencicipi sendiri penemuan saya, PlayerName.",
  str_homestory_N21yongchi_90020302_20_dialog_content = "Aku akan bertanggung jawab merekrut penguji. Anda mulai bekerja!",
  str_homestory_N21yongchi_90020303_1_dialog_content = "Hmm. Kepada siapa saya harus bertanya?",
  str_homestory_N21yongchi_90020303_2_dialog_content = "Mengapa, jika tidak PlayerName!",
  str_homestory_N21yongchi_90020303_3_dialog_content = "Apa yang Anda pikirkan begitu dalam?",
  str_homestory_N21yongchi_90020303_4_dialog_content = "Oh! Bangsat.",
  str_homestory_N21yongchi_90020303_5_dialog_content = "(Saya ingat Brock bahkan bisa meminum minuman protein telur cacing pasir.)",
  str_homestory_N21yongchi_90020303_6_dialog_content = "(Brock, temanku, aku minta maaf atas apa yang akan kulakukan padamu.)",
  str_homestory_N21yongchi_90020303_7_dialog_content = "Hei, kenapa kau basah kuyup?",
  str_homestory_N21yongchi_90020303_8_dialog_content = "Ini? Yah, saya baru saja melakukan 100 push-up, 100 sit-up, dan 100 squat.",
  str_homestory_N21yongchi_90020303_9_dialog_content = "Itu membuatku menghangat. Kemudian saya berlari sejauh 10 kilometer.",
  str_homestory_N21yongchi_90020303_10_dialog_content = "Ini adalah rutinitas favorit bagi anggota Rediesel Wrench di hari libur mereka.",
  str_homestory_N21yongchi_90020303_11_dialog_content = "Itu hari libur? Bagaimanapun, Anda harus menjadi panas setelah semua latihan itu.",
  str_homestory_N21yongchi_90020303_12_dialog_content = "Bagaimana Anda ingin mencoba rasa baru es krim?",
  str_homestory_N21yongchi_90020303_13_dialog_content = "Ini akan membantu mengisi kembali energi Anda dan membuat Anda lebih kuat.",
  str_homestory_N21yongchi_90020303_14_dialog_content = "Kedengarannya pintar!",
  str_homestory_N21yongchi_90020303_15_dialog_content = "Saya tahu Anda mendukung saya lebih dari Sinsa!",
  str_homestory_N21yongchi_90020303_16_dialog_content = "Ayo. Dimana es krim yang enak ini?",
  str_homestory_N21yongchi_90020303_17_dialog_content = "Di sini, cobalah!",
  str_homestory_N21yongchi_90020303_18_dialog_content = "Jilat jilat.",
  str_homestory_N21yongchi_90020303_19_dialog_content = "Slurp.",
  str_homestory_N21yongchi_90020303_20_dialog_content = "<color=#e8d9bb>Duar!</color>",
  str_homestory_N21yongchi_90020303_21_dialog_content = "Wow!!",
  str_homestory_N21yongchi_90020303_22_dialog_content = "Ada apa dengan es krim ini?",
  str_homestory_N21yongchi_90020303_23_dialog_content = "Ketika saya menelannya, saya merasa seperti seseorang telah meninju perut saya.",
  str_homestory_N21yongchi_90020303_24_dialog_content = "Itu trik licik. Bahkan lebih licik dari Sinsa.",
  str_homestory_N21yongchi_90020303_25_dialog_content = "T-tunggu sebentar. Biarkan saya memikirkan... Maksud saya, jelaskan!",
  str_homestory_N21yongchi_90020303_26_dialog_content = "Saya tahu! Mungkin... itu cara melatih untuk menerima pukulan?",
  str_homestory_N21yongchi_90020303_27_dialog_content = "Maksud saya, Anda membutuhkan lebih dari sekadar otot untuk mengalahkan Sinsa, bukan?",
  str_homestory_N21yongchi_90020303_28_dialog_content = "Anda harus bisa terus berjuang, bahkan setelah menerima pukulan, jika Anda ingin tertawa terakhir.",
  str_homestory_N21yongchi_90020303_29_dialog_content = "...",
  str_homestory_N21yongchi_90020303_30_dialog_content = "...",
  str_homestory_N21yongchi_90020303_31_dialog_content = "Kamu jenius!",
  str_homestory_N21yongchi_90020303_32_dialog_content = "Apakah ada lagi? Bagi dong?",
  str_homestory_N21yongchi_90020304_1_dialog_content = "Pemimpin cincin Jeno.",
  str_homestory_N21yongchi_90020304_2_dialog_content = "Oh, halo PlayerName.",
  str_homestory_N21yongchi_90020304_3_dialog_content = "Apakah Anda sudah membuat es krim? Aku seharusnya tahu kamu akan melakukannya.",
  str_homestory_N21yongchi_90020304_4_dialog_content = "Nah, ini hanya sampel.",
  str_homestory_N21yongchi_90020304_5_dialog_content = "Tapi kudengar kau seorang gourmet sejati, jadi...",
  str_homestory_N21yongchi_90020304_6_dialog_content = "Saya tahu. Anda ingin saya mencobanya, bukan?",
  str_homestory_N21yongchi_90020304_7_dialog_content = "Saya tidak tertarik pada makanan manis. Tapi itu ide saya, setelah semua.",
  str_homestory_N21yongchi_90020304_8_dialog_content = "Biarkan aku mencicipi.",
  str_homestory_N21yongchi_90020304_9_dialog_content = "Slurp.",
  str_homestory_N21yongchi_90020304_10_dialog_content = "A-apa ini?",
  str_homestory_N21yongchi_90020304_11_dialog_content = "Ini bukan kembang api beku. Ini adalah guntur di dalam kepalaku.",
  str_homestory_N21yongchi_90020304_12_dialog_content = "Itu sangat... tabu. Rasa terlarang.",
  str_homestory_N21yongchi_90020304_13_dialog_content = "Namun begitu mempesona.",
  str_homestory_N21yongchi_90020304_14_dialog_content = "...",
  str_homestory_N21yongchi_90020304_15_dialog_content = "Jeno, kamu baik-baik saja?",
  str_homestory_N21yongchi_90020304_16_dialog_content = "Ambil ini, PlayerName.",
  str_homestory_N21yongchi_90020304_17_dialog_content = "A-apa itu?",
  str_homestory_N21yongchi_90020304_18_dialog_content = "Sebuah mesin es krim.",
  str_homestory_N21yongchi_90020304_19_dialog_content = "Pendahulu saya pernah berkata kepada saya—",
  str_homestory_N21yongchi_90020304_20_dialog_content = "Jika Anda pernah menemukan seseorang yang es krimnya membuat selera Anda berdenyut, berikan hadiah ini kepada mereka.",
  str_homestory_N21yongchi_90020304_21_dialog_content = "Mesin es krim ini telah bersama Emerald selama bertahun-tahun. Saya harap ini melayani Anda dengan baik.",
  str_homestory_N21yongchi_90020304_22_dialog_content = "Dan Anda menggunakannya untuk membawa rasa itu ke lebih banyak mulut.",
  str_homestory_N21yongchi_90020304_23_dialog_content = "Boo-hoo... Aku tersentuh.",
  str_homestory_N21yongchi_90020304_24_dialog_content = "Terima kasih, Jeno!",
  str_homestory_N21yongchi_90020305_1_dialog_content = "Vice, aku kembali!",
  str_homestory_N21yongchi_90020305_2_dialog_content = "Besar, PlayerName.",
  str_homestory_N21yongchi_90020305_3_dialog_content = "Apa yang semua orang pikirkan tentang es krim saya?",
  str_homestory_N21yongchi_90020305_4_dialog_content = "Sehat! Brock menilainya sangat tinggi.",
  str_homestory_N21yongchi_90020305_5_dialog_content = "Dia mengatakan itu akan sangat membantu dalam rutinitas latihan fisiknya.",
  str_homestory_N21yongchi_90020305_6_dialog_content = "Hmm. Saya tidak menyadari bahwa dia adalah pria dengan selera yang bagus.",
  str_homestory_N21yongchi_90020305_7_dialog_content = "Saya benar-benar menambahkan sekaleng daging kaleng bergizi baru dari Illumina ke dalam campuran.",
  str_homestory_N21yongchi_90020305_8_dialog_content = "Jadi mengapa Anda harus menambahkan daging ke es krim ...",
  str_homestory_N21yongchi_90020305_9_dialog_content = "Oh. Ada ulasan lain?",
  str_homestory_N21yongchi_90020305_10_dialog_content = "Ya! Jeno bilang itu enak.",
  str_homestory_N21yongchi_90020305_11_dialog_content = "Dan dia bahkan memberi kami mesin es krim ini.",
  str_homestory_N21yongchi_90020305_12_dialog_content = "Luar biasa! Itu berarti semua orang pasti akan menikmati es krim baru saya.",
  str_homestory_N21yongchi_90020305_13_dialog_content = "Dan dengan bantuan mesin ini, akan lebih mudah untuk membuatnya.",
  str_homestory_N21yongchi_90020305_14_dialog_content = "Kami akan seefisien pabrik pengalengan daging.",
  str_homestory_N21yongchi_90020305_15_dialog_content = "Perbandingan yang aneh, tapi oke...",
  str_homestory_N21yongchi_90020305_16_dialog_content = "Haruskah saya mencobanya juga, sebelum kami menawarkannya kepada publik...",
  str_homestory_N21yongchi_90020306_1_dialog_content = "Oke, semuanya sudah beres.",
  str_homestory_N21yongchi_90020306_2_dialog_content = "Sekarang semua orang bisa menikmati es krim Vice.",
  str_homestory_N21yongchi_90020306_3_dialog_content = "Hmm. Haruskah saya mencobanya, atau tidak?",
  str_homestory_N21yongchi_90020306_4_dialog_content = "Ha ha. Lupakan saja, mungkin saya akan memilikinya nanti.",
  str_homestory_N21yongchi_90020401_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020401_2_dialog_content = "Petugas Vivian!",
  str_homestory_N21yongchi_90020401_3_dialog_content = "Anda terlihat khawatir tentang sesuatu. Adakah yang bisa saya bantu?",
  str_homestory_N21yongchi_90020401_4_dialog_content = "Wow, bagaimana Anda bisa tahu?",
  str_homestory_N21yongchi_90020401_5_dialog_content = "Caelestite memang mengesankan, mampu merasakan emosi sekecil apa pun dari orang lain.",
  str_homestory_N21yongchi_90020401_6_dialog_content = "Ha ha. Mungkin cara alis Anda mengerut membantu.",
  str_homestory_N21yongchi_90020401_7_dialog_content = "Biar kutebak. Petugas Philyshy hilang lagi?",
  str_homestory_N21yongchi_90020401_8_dialog_content = "Ya, dan dia terlambat dengan laporan intel penting.",
  str_homestory_N21yongchi_90020401_9_dialog_content = "Tidak ada yang bisa menemukannya di mana pun.",
  str_homestory_N21yongchi_90020401_10_dialog_content = "Dia benar-benar sakit kepala.",
  str_homestory_N21yongchi_90020401_11_dialog_content = "(Philyshy telah menyelinap untuk tidur siang akhir-akhir ini... mungkin dia di dekat air?)",
  str_homestory_N21yongchi_90020401_12_dialog_content = "Saya pikir saya punya ide di mana dia mungkin.",
  str_homestory_N21yongchi_90020401_13_dialog_content = "Dengan serius? Akan sangat membantu jika Anda bisa menemukannya.",
  str_homestory_N21yongchi_90020401_14_dialog_content = "Tunggu sementara aku pergi dan mencarinya.",
  str_homestory_N21yongchi_90020401_15_dialog_content = "Oh terima kasih, PlayerName!",
  str_homestory_N21yongchi_90020402_1_dialog_content = "Hai! Merpati!",
  str_homestory_N21yongchi_90020402_2_dialog_content = "Waaaaaaaah—",
  str_homestory_N21yongchi_90020402_3_dialog_content = "Siapa ini? Siapa yang membuat keributan seperti itu?",
  str_homestory_N21yongchi_90020402_4_dialog_content = "PlayerName, itu kamu?",
  str_homestory_N21yongchi_90020402_5_dialog_content = "Kenapa kamu malas-malasan di sini, Dove?",
  str_homestory_N21yongchi_90020402_6_dialog_content = "S-Malas? aku tidak!",
  str_homestory_N21yongchi_90020402_7_dialog_content = "Aku hanya ingin tidur siang karena aku sudah bekerja sangat keras. Dan kemudian Anda memberi saya ketakutan seperti itu.",
  str_homestory_N21yongchi_90020402_8_dialog_content = "Oh? Jadi Anda sudah selesai mengirimkan semua surat Anda?",
  str_homestory_N21yongchi_90020402_9_dialog_content = "Oh, surat-suratnya... Aku akan langsung ke sana, segera setelah aku tertidur.",
  str_homestory_N21yongchi_90020402_10_dialog_content = "Dan apa yang Anda lakukan? Anda tidak dapat mengganggu tidur saya seperti itu tanpa menjelaskan diri sendiri.",
  str_homestory_N21yongchi_90020402_11_dialog_content = "Oh ya. Maaf tentang itu. Aku sebenarnya mencari Philyshy.",
  str_homestory_N21yongchi_90020402_12_dialog_content = "Di sini, dapatkan voucher untuk es krim sebagai permintaan maaf. Jika Anda berada di dekat kolam renang, Anda dapat mencoba salah satu rasa baru Vice.",
  str_homestory_N21yongchi_90020402_13_dialog_content = "Oke. Kurasa aku akan memaafkanmu kalau begitu. Tapi aku tidak tahu di mana Philyshy.",
  str_homestory_N21yongchi_90020402_14_dialog_content = "Bagaimanapun, saya akan lebih mungkin untuk mengunjungi jika kolam renang memiliki tempat untuk tidur. Itu lebih penting daripada es krim, kurasa.",
  str_homestory_N21yongchi_90020402_15_dialog_content = "Mungkin kursi santai di bawah payung?",
  str_homestory_N21yongchi_90020402_16_dialog_content = "Hanya hal-hal penting sehingga kita pekerja keras dapat bersantai dengan benar.",
  str_homestory_N21yongchi_90020402_17_dialog_content = "Kamu benar. Biarkan aku berpikir.",
  str_homestory_N21yongchi_90020402_18_dialog_content = "Tempat untuk bersantai... untuk bersantai... Philyshy... Mengerti!",
  str_homestory_N21yongchi_90020402_19_dialog_content = "Jangan lupa untuk mengunjungi taman air, Dove!",
  str_homestory_N21yongchi_90020402_20_dialog_content = "Hah? Oke, tentu.",
  str_homestory_N21yongchi_90020403_1_dialog_content = "PlayerName, apa yang kaulakukan?",
  str_homestory_N21yongchi_90020403_2_dialog_content = "Saya akan membuat beberapa kursi santai dari kayu.",
  str_homestory_N21yongchi_90020403_3_dialog_content = "Bagaimana menurutmu? Mereka baik, kan?",
  str_homestory_N21yongchi_90020403_4_dialog_content = "Ya. Aku tahu tentang keterampilan komando medan perangmu, tapi... Sepertinya kamu masih memiliki beberapa kejutan yang tersembunyi.",
  str_homestory_N21yongchi_90020403_5_dialog_content = "Sekarang siapa pun yang datang mengunjungi taman air dapat beristirahat kapan saja mereka mau.",
  str_homestory_N21yongchi_90020403_6_dialog_content = "Taman air ini semakin nyaman.",
  str_homestory_N21yongchi_90020403_7_dialog_content = "Ya. Sekarang orang dapat memiliki tempat untuk berbaring jika mereka lelah berenang atau ingin menikmati es krim.",
  str_homestory_N21yongchi_90020403_8_dialog_content = "Dan itu bukan yang terbaik. Kursi santai ini memiliki kekuatan rahasia.",
  str_homestory_N21yongchi_90020403_9_dialog_content = "Sebuah kekuatan rahasia?",
  str_homestory_N21yongchi_90020403_10_dialog_content = "Setelah saya membuatnya dan mengaturnya, Anda akan dapat melihat hasilnya!",
  str_homestory_N21yongchi_90020404_1_dialog_content = "Oke, ini semua berkilau bersih sekarang.",
  str_homestory_N21yongchi_90020404_2_dialog_content = "Sekarang yang perlu saya lakukan adalah meletakkan kursi santai dan menunggu keajaiban terjadi.",
  str_homestory_N21yongchi_90020404_3_dialog_content = "Dan aku harus mengambil kesempatan untuk memanggil Petugas Vivian.",
  str_homestory_N21yongchi_90020405_1_dialog_content = "Zzzz... Zzzz... meong.",
  str_homestory_N21yongchi_90020405_2_dialog_content = "Itu berhasil! Mengikuti jejak kaki menuju Philyshy!",
  str_homestory_N21yongchi_90020405_3_dialog_content = "Kenapa kamu terlihat tertidur bahkan ketika kamu sedang berdiri?",
  str_homestory_N21yongchi_90020405_4_dialog_content = "Hah? Tenanglah, PlayerName. Aku baru saja bangun.",
  str_homestory_N21yongchi_90020405_5_dialog_content = "Sebaiknya kau berhenti tidur.",
  str_homestory_N21yongchi_90020405_6_dialog_content = "Seseorang mencarimu.",
  str_homestory_N21yongchi_90020405_7_dialog_content = "S-Siapa mengeong? Aku baru bangun lima menit. Aku ingin...",
  str_homestory_N21yongchi_90020405_8_dialog_content = "Phi—ly—malu—!",
  str_homestory_N21yongchi_90020405_9_dialog_content = "Meong?!",
  str_homestory_N21yongchi_90020405_10_dialog_content = "O-Petugas Vivian?",
  str_homestory_N21yongchi_90020405_11_dialog_content = "K-Kenapa kamu di sini meow?",
  str_homestory_N21yongchi_90020405_12_dialog_content = "Mengapa Anda tidak mengirimkan informasi yang saya minta?",
  str_homestory_N21yongchi_90020405_13_dialog_content = "Dan mengapa saya tidak dapat menemukan Anda di mana pun? Anda tidak akan menghindari saya, kan?",
  str_homestory_N21yongchi_90020405_14_dialog_content = "A-Menghindarimu? Seolah aku akan...",
  str_homestory_N21yongchi_90020405_15_dialog_content = "L-Biarkan aku menjelaskan meow...",
  str_homestory_N21yongchi_90020405_16_dialog_content = "Oke, Anda bisa melakukannya dalam perjalanan kembali.",
  str_homestory_N21yongchi_90020405_17_dialog_content = "Dan jangan khawatir jika Anda tidak dapat menjelaskan sepenuhnya sekarang. Saya punya banyak waktu malam ini untuk mendengarkan penjelasan yang lengkap dan komprehensif.",
  str_homestory_N21yongchi_90020405_18_dialog_content = "Oh meong. Anda benar-benar terlihat menakutkan, Petugas Vivian.",
  str_homestory_N21yongchi_90020405_19_dialog_content = "Ini semua karena PlayerName dan kursi santai yang indah itu.",
  str_homestory_N21yongchi_90020405_20_dialog_content = "Aku akan ikut denganmu seperti yang diperintahkan meow.",
  str_homestory_N21yongchi_90020405_21_dialog_content = "PlayerName, apakah itu kekuatan rahasia yang Anda sebutkan?",
  str_homestory_N21yongchi_90020405_22_dialog_content = "Sebuah perangkap Philyshy... sangat pintar.",
  str_homestory_N21yongchi_90020405_23_dialog_content = "Tentu saja. Kupikir dia mungkin sengaja bersembunyi dari semua orang, tapi dia tidak akan bisa menolak tempat istirahat yang nyaman.",
  str_homestory_N21yongchi_90020405_24_dialog_content = "Dan benar saja, dia muncul.",
  str_homestory_N21yongchi_90020405_25_dialog_content = "Sekarang saya yakin kursi santai itu nyaman.",
  str_homestory_N21yongchi_90020501_1_dialog_content = "PlayerName!",
  str_homestory_N21yongchi_90020501_2_dialog_content = "Apa yang sangat kamu khawatirkan?",
  str_homestory_N21yongchi_90020501_3_dialog_content = "Taman air terlihat indah. Apakah ada hal lain yang mengganggu Anda?",
  str_homestory_N21yongchi_90020501_4_dialog_content = "Yah... Saya ingin membuatnya lebih baik, sehingga lebih banyak orang dapat menikmatinya.",
  str_homestory_N21yongchi_90020501_5_dialog_content = "Saya sudah mencoba menambahkan beberapa tanaman ke dalam air untuk membuat udara lebih segar.",
  str_homestory_N21yongchi_90020501_6_dialog_content = "Dan juga membuka beberapa warung jajanan lagi.",
  str_homestory_N21yongchi_90020501_7_dialog_content = "Saya bahkan berpikir untuk memiliki tas buta untuk dijual seperti yang dilakukan Jomu.",
  str_homestory_N21yongchi_90020501_8_dialog_content = "Oh, tas buta... Aku tidak akan melakukan itu.",
  str_homestory_N21yongchi_90020501_9_dialog_content = "Dan apakah ada hal lain yang ingin Anda tingkatkan?",
  str_homestory_N21yongchi_90020501_10_dialog_content = "Saya tidak yakin. Saya hanya terus berpikir ada sesuatu yang hilang ketika saya membandingkannya dengan ingatan saya tentang Zamrud.",
  str_homestory_N21yongchi_90020501_11_dialog_content = "Mungkin tidak begitu... hidup?",
  str_homestory_N21yongchi_90020501_12_dialog_content = "Tampaknya merasa sedikit tidak ceria.",
  str_homestory_N21yongchi_90020501_13_dialog_content = "Mungkin Anda membutuhkan seseorang seperti Rainbow, pembawa acara untuk membuat semua orang bersemangat.",
  str_homestory_N21yongchi_90020501_14_dialog_content = "Orang-orang akan hidup jika kita memiliki seseorang yang dapat menciptakan suasana bahagia.",
  str_homestory_N21yongchi_90020501_15_dialog_content = "Itu masuk akal.",
  str_homestory_N21yongchi_90020501_16_dialog_content = "Tapi saya tidak bisa berkeliaran di tepi kolam melakukan itu sepanjang waktu.",
  str_homestory_N21yongchi_90020501_17_dialog_content = "Biarkan aku berpikir. Bagaimana cara menciptakan suasana?",
  str_homestory_N21yongchi_90020501_18_dialog_content = "Bagaimana dengan musik? Banyak tempat yang berbeda menggunakan musik untuk menciptakan suasana yang sesuai.",
  str_homestory_N21yongchi_90020501_19_dialog_content = "Di Umbraton, beberapa toko memutar musik klasik untuk membantu pelanggan merasa santai dan seperti di rumah sendiri.",
  str_homestory_N21yongchi_90020501_20_dialog_content = "Dan itu berarti mereka menghabiskan lebih banyak.",
  str_homestory_N21yongchi_90020501_21_dialog_content = "Tapi di mana saya akan menemukan peralatannya?",
  str_homestory_N21yongchi_90020501_22_dialog_content = "Saya pikir saya ingat musik di Emerald.",
  str_homestory_N21yongchi_90020501_23_dialog_content = "Ya kamu benar. Mereka memainkannya di antara kompetisi.",
  str_homestory_N21yongchi_90020501_24_dialog_content = "Kalau begitu aku harus pergi dan bertanya pada Rainbow lagi.",
  str_homestory_N21yongchi_90020502_1_dialog_content = "Rainbow!",
  str_homestory_N21yongchi_90020502_2_dialog_content = "PlayerName, Anda semua berkeringat lagi. Apa terburu-buru?",
  str_homestory_N21yongchi_90020502_3_dialog_content = "Aku bilang jangan terlalu terburu-buru. Lagipula aku tidak akan kemana-mana.",
  str_homestory_N21yongchi_90020502_4_dialog_content = "Apakah semua orang menyukai hadiah yang saya berikan kepada Anda?",
  str_homestory_N21yongchi_90020502_5_dialog_content = "Ya! Terima kasih, Rainbow. Dan Jeno juga.",
  str_homestory_N21yongchi_90020502_6_dialog_content = "Banyak Aurorian yang tidak bisa berenang dapat menikmati taman air, terima kasih untuk kalian berdua.",
  str_homestory_N21yongchi_90020502_7_dialog_content = "Hehe. Sepertinya Aurorian memiliki ketertarikan alami terhadap air.",
  str_homestory_N21yongchi_90020502_8_dialog_content = "Siapa yang bisa menolak pelampung santai yang bagus?",
  str_homestory_N21yongchi_90020502_9_dialog_content = "Yah, selama Anda menyukainya. Jadi, apa kali ini?",
  str_homestory_N21yongchi_90020502_10_dialog_content = "Yah... Aku ingin bisa bermain musik di taman air.",
  str_homestory_N21yongchi_90020502_11_dialog_content = "Oh. Itu tidak akan murah.",
  str_homestory_N21yongchi_90020502_12_dialog_content = "Dan itu bukan sesuatu yang bisa saya putuskan sendiri. Anda harus berbicara dengan Jeno.",
  str_homestory_N21yongchi_90020502_13_dialog_content = "Dia bukan hanya seorang pelukis yang tajam, kau tahu. Dia juga memiliki banyak ide tentang musik.",
  str_homestory_N21yongchi_90020502_14_dialog_content = "Dia pria yang sangat berbudaya, untuk seorang pelaut.",
  str_homestory_N21yongchi_90020502_15_dialog_content = "Ha ha. Terima kasih, Rainbow.",
  str_homestory_N21yongchi_90020502_16_dialog_content = "Aku akan pergi dan berbicara dengannya.",
  str_homestory_N21yongchi_90020503_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020503_2_dialog_content = "Kenapa perutku terasa lucu saat melihatmu?",
  str_homestory_N21yongchi_90020503_3_dialog_content = "Mungkin... ada hubungannya dengan es krim itu?",
  str_homestory_N21yongchi_90020503_4_dialog_content = "Saya kira demikian. Saya tidak dapat mengingat rasanya, tetapi ingatan akan pengalaman itu masih sangat jelas.",
  str_homestory_N21yongchi_90020503_5_dialog_content = "Meskipun sepertinya perutku yang mengingatnya, bukan aku.",
  str_homestory_N21yongchi_90020503_6_dialog_content = "Ini aneh. Sangat aneh memang.",
  str_homestory_N21yongchi_90020503_7_dialog_content = "Nah, jika Anda ingin lebih, Anda selalu diterima di Taman Air Cloud Gardens.",
  str_homestory_N21yongchi_90020503_8_dialog_content = "Terima kasih. Tapi saya berusaha menghindari makanan manis.",
  str_homestory_N21yongchi_90020503_9_dialog_content = "Jika saya menjadi gemuk, saya tidak akan memiliki fleksibilitas yang saya butuhkan untuk pertunjukan sulap saya.",
  str_homestory_N21yongchi_90020503_10_dialog_content = "Oh, tapi apakah itu manis? Mengapa otakku menjadi kabur setiap kali aku mencoba mengingat rasa itu?",
  str_homestory_N21yongchi_90020503_11_dialog_content = "Oke, tentu, er, mari kita bahas es krim di lain waktu.",
  str_homestory_N21yongchi_90020503_12_dialog_content = "Aku butuh bantuan, Jeno. Di mana saya bisa membeli perlengkapan musik?",
  str_homestory_N21yongchi_90020503_13_dialog_content = "Oh begitu. Anda ingin bermain musik di taman air dan menciptakan suasana yang lebih baik, bukan?",
  str_homestory_N21yongchi_90020503_14_dialog_content = "Seharusnya aku tahu tebakanmu benar, Jeno.",
  str_homestory_N21yongchi_90020503_15_dialog_content = "Tentu. Dan kebetulan yang lucu...",
  str_homestory_N21yongchi_90020503_16_dialog_content = "Saya kebetulan memiliki beberapa peralatan lama yang bisa saya jual kepada Anda.",
  str_homestory_N21yongchi_90020503_17_dialog_content = "Oh terimakasih-",
  str_homestory_N21yongchi_90020503_18_dialog_content = "Untuk 50 juta Nightium.",
  str_homestory_N21yongchi_90020503_19_dialog_content = "Apa!?",
  str_homestory_N21yongchi_90020503_20_dialog_content = "I-itu terlalu banyak.",
  str_homestory_N21yongchi_90020503_21_dialog_content = "Sama sekali tidak. Kita berbicara tentang dek DJ koleksi yang sangat langka. Saya membayar dua kali lipat untuk itu ketika saya mendapatkannya.",
  str_homestory_N21yongchi_90020503_22_dialog_content = "Tapi karena kita berteman, rasanya tidak tepat untuk menjual Dek DJ Suffering Knight yang legendaris.",
  str_homestory_N21yongchi_90020503_23_dialog_content = "Dan itu bukan sesuatu yang saya ingin berikan nilai uang.",
  str_homestory_N21yongchi_90020503_24_dialog_content = "Tapi saya ingin Anda membuktikan bahwa Anda layak untuk itu.",
  str_homestory_N21yongchi_90020503_25_dialog_content = "Saya telah menghabiskan hari-hari bahagia yang tak terhitung jumlahnya dengannya. Anda harus menunjukkan kepada saya bahwa Anda akan menjaganya.",
  str_homestory_N21yongchi_90020503_26_dialog_content = "(Oh, saya mengerti. Jeno sebenarnya orang yang sangat bernostalgia.)",
  str_homestory_N21yongchi_90020503_27_dialog_content = "Jadi, tunjukkan betapa Anda menginginkannya!",
  str_homestory_N21yongchi_90020503_28_dialog_content = "Dengan membawakan saya ikan paling langka dan paling berharga yang dapat ditemukan di bagian ini.",
  str_homestory_N21yongchi_90020503_29_dialog_content = "aku akan!",
  str_homestory_N21yongchi_90020504_1_dialog_content = "Apakah Anda mendapatkan mereka?",
  str_homestory_N21yongchi_90020504_2_dialog_content = "Ya!({1}/{2})",
  str_homestory_N21yongchi_90020504_3_dialog_content = "Saya tidak berpikir Anda akan bisa.",
  str_homestory_N21yongchi_90020504_4_dialog_content = "Tapi pertahankan. Aku tidak pernah benar-benar menginginkan mereka.",
  str_homestory_N21yongchi_90020504_5_dialog_content = "Aku hanya ingin melihat seberapa kuat tekadmu. Seberapa keras Anda akan bekerja.",
  str_homestory_N21yongchi_90020504_6_dialog_content = "Jadi, apakah saya lulus ujian?",
  str_homestory_N21yongchi_90020504_7_dialog_content = "Tentu saja. Dek DJ adalah milik Anda.",
  str_homestory_N21yongchi_90020504_8_dialog_content = "Dan saya yakin nadanya yang indah akan memberi Anda pemahaman yang lebih baik tentang kebenaran dunia ini.",
  str_homestory_N21yongchi_90020504_9_dialog_content = "Tolong, jaga baik-baik.",
  str_homestory_N21yongchi_90020504_10_dialog_content = "Tentu saja, Jeno! Saya akan.",
  str_homestory_N21yongchi_90020504_11_dialog_content = "Hampir sampai!",
  str_homestory_N21yongchi_90020504_12_dialog_content = "Bagus. Bukti kan kepada saya.",
  str_homestory_N21yongchi_90020505_1_dialog_content = "Ya! Sekarang kita telah mengosongkan ruang, dan kita dapat mengatur Dek DJ Suffering Knight.",
  str_homestory_N21yongchi_90020505_2_dialog_content = "Meskipun ... bagaimana cara kerjanya?",
  str_homestory_N21yongchi_90020601_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020601_2_dialog_content = "...",
  str_homestory_N21yongchi_90020601_3_dialog_content = "PlayerName!",
  str_homestory_N21yongchi_90020601_4_dialog_content = "...",
  str_homestory_N21yongchi_90020601_5_dialog_content = "Caelestit yang buruk!",
  str_homestory_N21yongchi_90020601_6_dialog_content = "Hah? Apa?",
  str_homestory_N21yongchi_90020601_7_dialog_content = "Fi, itu kamu!",
  str_homestory_N21yongchi_90020601_8_dialog_content = "Anda berada bermil-mil jauhnya. Apa yang sedang kamu pikirkan?",
  str_homestory_N21yongchi_90020601_9_dialog_content = "Kamu terus mengabaikanku. Seorang ekstrozoologis seperti saya layak mendapatkan lebih banyak rasa hormat.",
  str_homestory_N21yongchi_90020601_10_dialog_content = "Maaf maaf!",
  str_homestory_N21yongchi_90020601_11_dialog_content = "Saya sedang melamun, membayangkan banyak orang menikmati taman air.",
  str_homestory_N21yongchi_90020601_12_dialog_content = "Ck. Aku akan memaafkanmu, kurasa.",
  str_homestory_N21yongchi_90020601_13_dialog_content = "Dan, eh... Sebenarnya, saya ingin masuk dan menikmati kolam renang.",
  str_homestory_N21yongchi_90020601_14_dialog_content = "Oh? Masuklah. Gratis.",
  str_homestory_N21yongchi_90020601_15_dialog_content = "Saya tidak khawatir tentang harga!",
  str_homestory_N21yongchi_90020601_16_dialog_content = "H-Apakah kamu lupa?",
  str_homestory_N21yongchi_90020601_17_dialog_content = "Aku tidak... Yah, aku bukan perenang terbaik.",
  str_homestory_N21yongchi_90020601_18_dialog_content = "Oh ya. Aku ingat sekarang.",
  str_homestory_N21yongchi_90020601_19_dialog_content = "Mengapa tidak mencoba dengan cincin renang?",
  str_homestory_N21yongchi_90020601_20_dialog_content = "Hah. Itu untuk anak-anak. Saya tidak ingin salah satu dari mereka!",
  str_homestory_N21yongchi_90020601_21_dialog_content = "Lalu hanya ada satu pilihan.",
  str_homestory_N21yongchi_90020601_22_dialog_content = "Jika Anda tidak ingin menggunakan cincin renang, Anda harus belajar berenang.",
  str_homestory_N21yongchi_90020601_23_dialog_content = "Tepat. Itu sebabnya saya datang untuk berbicara dengan Anda, PlayerName.",
  str_homestory_N21yongchi_90020601_24_dialog_content = "Saya menawarkan kesempatan bagus untuk membiarkan Anda membantu saya, kecantikan ekstrozoologi yang hebat, Anda tahu.",
  str_homestory_N21yongchi_90020601_25_dialog_content = "Jangan lewatkan!",
  str_homestory_N21yongchi_90020601_26_dialog_content = "Tapi... Aku harus menyambut semua orang, menjaga kamar ganti tetap rapi, dan membersihkan lantai dan kolam renang.",
  str_homestory_N21yongchi_90020601_27_dialog_content = "Saya khawatir saya tidak punya waktu untuk mengajari Anda, Fia.",
  str_homestory_N21yongchi_90020601_28_dialog_content = "Oh... K-Kau menolakku?",
  str_homestory_N21yongchi_90020601_29_dialog_content = "Tidak, tidak, bagaimana saya bisa melakukan itu?",
  str_homestory_N21yongchi_90020601_30_dialog_content = "Bagaimana dengan ini? Aku akan meminta Vice untuk mengajarimu.",
  str_homestory_N21yongchi_90020601_31_dialog_content = "Dia perenang yang jauh lebih baik daripada saya.",
  str_homestory_N21yongchi_90020601_32_dialog_content = "Hmm. Keburukan?",
  str_homestory_N21yongchi_90020601_33_dialog_content = "Baiklah kalau begitu. Saya dapat melihat Anda memiliki banyak pekerjaan, PlayerName.",
  str_homestory_N21yongchi_90020601_34_dialog_content = "Jadi tidak sopan jika saya bersikeras.",
  str_homestory_N21yongchi_90020601_35_dialog_content = "Berikut adalah beberapa hadiah kecil sebagai ucapan terima kasih.",
  str_homestory_N21yongchi_90020601_36_dialog_content = "Terima kasih, Fia!",
  str_homestory_N21yongchi_90020601_37_dialog_content = "Ya! Setelah aku belajar, kita bisa pergi berenang bersama.",
  str_homestory_N21yongchi_90020601_38_dialog_content = "Oke. Aku akan pergi mencari Vice.",
  str_homestory_N21yongchi_90020601_39_dialog_content = "Tentu. Aku akan menunggumu disini.",
  str_homestory_N21yongchi_90020602_1_dialog_content = "Hmm. Tikar tiup itu...",
  str_homestory_N21yongchi_90020602_2_dialog_content = "Ini sangat gaya Fia.",
  str_homestory_N21yongchi_90020602_3_dialog_content = "Saya pikir saya harus memindahkan kursi tiup sedikit.",
  str_homestory_N21yongchi_90020602_4_dialog_content = "Saya akan menyimpannya untuk saat ini jika ada pengunjung yang menabraknya.",
  str_homestory_N21yongchi_90020603_1_dialog_content = "Keburukan? Apa yang kamu lakukan di Menara Putih? Aku sedang mencarimu.",
  str_homestory_N21yongchi_90020603_2_dialog_content = "Hmm! PlayerName! Aku juga mencarimu.",
  str_homestory_N21yongchi_90020603_3_dialog_content = "Apa yang terjadi?",
  str_homestory_N21yongchi_90020603_4_dialog_content = "<color=#e8d9bb>Tok, tok!</color>",
  str_homestory_N21yongchi_90020603_5_dialog_content = "Agak memalukan... Sepertinya mesin es krimnya rusak.",
  str_homestory_N21yongchi_90020603_6_dialog_content = "Rusak?",
  str_homestory_N21yongchi_90020603_7_dialog_content = "Saya tidak begitu yakin.",
  str_homestory_N21yongchi_90020603_8_dialog_content = "Itu hanya berhenti. Dan saya sangat menikmati membuat semua rasa es krim baru saya.",
  str_homestory_N21yongchi_90020603_9_dialog_content = "Ah! Ayo! Bagaimana kita menyimpannya? Bukankah kita berjanji akan memberi semua orang musim panas yang menyenangkan?",
  str_homestory_N21yongchi_90020603_10_dialog_content = "Sepertinya Anda dan mesin es krim telah menjadi teman dekat.",
  str_homestory_N21yongchi_90020603_11_dialog_content = "Tentu saja! Kami telah bekerja keras berdampingan selama 20 jam sekarang, tanpa henti.",
  str_homestory_N21yongchi_90020603_12_dialog_content = "20 jam! Vice, Anda perlu istirahat.",
  str_homestory_N21yongchi_90020603_13_dialog_content = "Dan saya menduga masalah dengan mesin mungkin terkait dengan terlalu banyak pekerjaan.",
  str_homestory_N21yongchi_90020603_14_dialog_content = "Hmmm. Saya mungkin telah mengabaikan kemungkinan itu.",
  str_homestory_N21yongchi_90020603_15_dialog_content = "Mungkin ini salahku, itu rusak... Dan setelah kau bersusah payah mendapatkannya. Maaf, PlayerName.",
  str_homestory_N21yongchi_90020603_16_dialog_content = "Saya merencanakan rasa yang benar-benar menakjubkan untuk Anda nikmati.",
  str_homestory_N21yongchi_90020603_17_dialog_content = "Nah, itu adalah pemikiran yang diperhitungkan.",
  str_homestory_N21yongchi_90020603_18_dialog_content = "Apakah itu bertingkah aneh sebelum berhenti bekerja?",
  str_homestory_N21yongchi_90020603_19_dialog_content = "Biarkan aku berpikir. Saya pikir mungkin ada lampu merah berkedip.",
  str_homestory_N21yongchi_90020603_20_dialog_content = "Jadi mungkin itu tidak mendapatkan kekuatan yang cukup?",
  str_homestory_N21yongchi_90020603_21_dialog_content = "Jika Anda mengingat gambar-gambar di atas. Ada pohon dan batu.",
  str_homestory_N21yongchi_90020603_22_dialog_content = "Mungkin kita bisa memberinya kayu dan bijih dan melihat apa yang terjadi?",
  str_homestory_N21yongchi_90020603_23_dialog_content = "Meskipun saya tidak mengerti mengapa mesin es krim bekerja di atas kayu dan bijih.",
  str_homestory_N21yongchi_90020603_24_dialog_content = "Aku akan pergi dan mendapatkan beberapa pula. Kita lihat saja apa yang terjadi.",
  str_homestory_N21yongchi_90020604_1_dialog_content = "Apakah Anda mendapatkan kayunya?",
  str_homestory_N21yongchi_90020604_2_dialog_content = "Tentu saja.({1}/{2})",
  str_homestory_N21yongchi_90020604_3_dialog_content = "Terima kasih! Sekarang pergi dan temukan bijih.",
  str_homestory_N21yongchi_90020604_4_dialog_content = "Akan melakukan.",
  str_homestory_N21yongchi_90020604_5_dialog_content = "Tidak cukup.",
  str_homestory_N21yongchi_90020604_6_dialog_content = "Semoga beruntung! Aku akan berada di sini.",
  str_homestory_N21yongchi_90020605_1_dialog_content = "Apakah Anda mendapatkan bijihnya juga?",
  str_homestory_N21yongchi_90020605_2_dialog_content = "Ya.({1}/{2})",
  str_homestory_N21yongchi_90020605_3_dialog_content = "Anda selalu begitu cepat, PlayerName.",
  str_homestory_N21yongchi_90020605_4_dialog_content = "Mari kita lihat apakah itu berhasil.",
  str_homestory_N21yongchi_90020605_5_dialog_content = "Oke, saya sudah memasukkan semuanya.",
  str_homestory_N21yongchi_90020605_6_dialog_content = "Tidak ada yang akan berubah jika kita tidak mencobanya. Di sini, saya akan melakukannya.",
  str_homestory_N21yongchi_90020605_7_dialog_content = "<color=#e8d9bb>Keripik renyah.</color>",
  str_homestory_N21yongchi_90020605_8_dialog_content = "<color=#e8d9bb>Keripik renyah.</color>",
  str_homestory_N21yongchi_90020605_9_dialog_content = "Saya harap ini berhasil.",
  str_homestory_N21yongchi_90020605_10_dialog_content = "Yang bisa kita lakukan sekarang hanyalah berdoa.",
  str_homestory_N21yongchi_90020605_11_dialog_content = "Keripik renyah.",
  str_homestory_N21yongchi_90020605_12_dialog_content = "Eh... Vice...",
  str_homestory_N21yongchi_90020605_13_dialog_content = "Saya hanya ingin bertanya... Anda tidak menganiaya mesin es krim, kan?",
  str_homestory_N21yongchi_90020605_14_dialog_content = "Ha ha. Seolah-olah saya akan melakukan itu.",
  str_homestory_N21yongchi_90020605_15_dialog_content = "Keripik renyah.",
  str_homestory_N21yongchi_90020605_16_dialog_content = "Remuk-remas crunch-krak-krak.",
  str_homestory_N21yongchi_90020605_17_dialog_content = "Suka memberi makan bahan-bahan aneh, mungkin?",
  str_homestory_N21yongchi_90020605_18_dialog_content = "Hmm. Saya kira tidak demikian. Kecuali cangkang, tulang, dan seluruh ikan itu aneh.",
  str_homestory_N21yongchi_90020605_19_dialog_content = "Anda melakukan apa!?",
  str_homestory_N21yongchi_90020605_20_dialog_content = "Dan... Nah, jika asupan bahannya macet, saya mungkin akan memberinya pukulan yang bagus.",
  str_homestory_N21yongchi_90020605_21_dialog_content = "Tapi pukulan yang sangat akurat, saya janji!",
