  str_homestory_N21yongchi_90020605_23_dialog_content = "Aku tahu itu. Anda harus mencoba menjadi sedikit lebih lembut dengannya.",
  str_homestory_N21yongchi_90020605_24_dialog_content = "Mudah-mudahan itu hanya kehabisan daya. Kalau tidak, saya tidak tahu bagaimana kami akan memperbaikinya.",
  str_homestory_N21yongchi_90020605_25_dialog_content = "Aku tahu. Aku akan lebih berhati-hati.",
  str_homestory_N21yongchi_90020605_26_dialog_content = "PlayerName, ini luar biasa!",
  str_homestory_N21yongchi_90020605_27_dialog_content = "Saya masih tidak mengerti BAGAIMANA cara kerjanya. Tapi saya senang melakukannya!",
  str_homestory_N21yongchi_90020605_28_dialog_content = "Bagus sekali. Kami mendapatkan mesin es krim kembali dan berjalan.",
  str_homestory_N21yongchi_90020605_29_dialog_content = "Oh, aku hampir lupa kenapa aku datang.",
  str_homestory_N21yongchi_90020605_30_dialog_content = "Ini seperti ini: Fia ingin belajar berenang, dan saya tahu Anda perenang yang kuat.",
  str_homestory_N21yongchi_90020605_31_dialog_content = "Jadi mungkin Anda bisa mengajarinya, ketika Anda punya waktu?",
  str_homestory_N21yongchi_90020605_32_dialog_content = "Apa, itu saja?",
  str_homestory_N21yongchi_90020605_33_dialog_content = "Biarkan saya mengambil ini dan memperbaiki mesin es krim, dan kemudian saya akan pergi menemui Fia.",
  str_homestory_N21yongchi_90020605_34_dialog_content = "Katakan padanya untuk menungguku di tepi kolam renang. Saya akan menunjukkan kepadanya beberapa metode pelatihan terbaik Illumina.",
  str_homestory_N21yongchi_90020605_35_dialog_content = "Fia akan menurunkannya kali ini. Itu akan menjadi sesuatu untuk dirayakan!",
  str_homestory_N21yongchi_90020605_36_dialog_content = "Ini akan benar.",
  str_homestory_N21yongchi_90020605_37_dialog_content = "Sedikit lagi, ayo!",
  str_homestory_N21yongchi_90020606_1_dialog_content = "Puff... Aku lelah.",
  str_homestory_N21yongchi_90020606_2_dialog_content = "PlayerName, Anda tampak sangat sibuk.",
  str_homestory_N21yongchi_90020606_3_dialog_content = "Pasti melelahkan mengelola tempat sebesar itu.",
  str_homestory_N21yongchi_90020606_4_dialog_content = "Tentu saja. Saya perlu menjaga banyak hal yang berbeda di sini.",
  str_homestory_N21yongchi_90020606_5_dialog_content = "Tapi saya senang telah menciptakan tempat di mana setiap orang dapat menikmati diri mereka sendiri.",
  str_homestory_N21yongchi_90020606_6_dialog_content = "Itu benar, tetapi Anda tidak punya waktu untuk bersantai dan bersenang-senang sendiri, bukan?",
  str_homestory_N21yongchi_90020606_7_dialog_content = "Heh. Tidak, itu benar.",
  str_homestory_N21yongchi_90020606_8_dialog_content = "Saya telah bekerja dari fajar hingga senja akhir-akhir ini.",
  str_homestory_N21yongchi_90020606_9_dialog_content = "Ya. Seperti yang aku dan Vice pikirkan.",
  str_homestory_N21yongchi_90020606_10_dialog_content = "Itulah sebabnya kami datang untuk membantu.",
