  str_homestory_N21yongchi_90020606_12_dialog_content = "Maka Anda akan dapat menikmatinya juga.",
  str_homestory_N21yongchi_90020606_13_dialog_content = "Dengan serius?",
  str_homestory_N21yongchi_90020606_14_dialog_content = "Tentu saja. Anda layak mendapatkannya.",
  str_homestory_N21yongchi_90020606_15_dialog_content = "Maksudku, kita tidak bisa selalu mendapat manfaat dari semua kerja kerasmu, bukan?",
  str_homestory_N21yongchi_90020606_16_dialog_content = "Luar biasa. Saya sudah berharap untuk melakukan ini!",
  str_homestory_N21yongchi_90020606_17_dialog_content = "Sekarang aku akan menikmati diriku sendiri dari fajar hingga senja.",
  str_homestory_N21yongchi_90020606_18_dialog_content = "Saya akan berenang 300 putaran di kolam renang.",
  str_homestory_N21yongchi_90020606_19_dialog_content = "Lalu aku akan mengisi diriku dengan es krim dan tertidur di kursi santai.",
  str_homestory_N21yongchi_90020606_20_dialog_content = "Besar. Pergilah bersenang-senang!",
  str_homestory_N21yongchi_90020606_21_dialog_content = "Ini musim panasmu juga, ingat.",
